# -*- coding: utf-8 -*-
# 의견 보내기
#  · 새 파일 lib/screens/feedback_screen.dart (종류 3개 · 글 · 이메일(선택) · 보내기 → Cloudflare 저장 + ceo@knexm.com 메일)
#  · ⋮ 메뉴: '앱 평가하기' 바로 아래에 '의견 보내기' 줄
#  · 도움말 맨 아래: '이메일 문의' 버튼 → '의견 보내기' 화면 (메일 주소는 아래에 그대로, 누르면 메일 앱)
#  · 글자는 23개 언어 (화면 파일 안 번역표)
import os, sys, base64

NEW = os.path.join('lib', 'screens', 'feedback_screen.dart')
P = {
    'menu': os.path.join('lib', 'widgets', 'more_menu_sheet.dart'),
    'help': os.path.join('lib', 'screens', 'settings_help_screen.dart'),
}
TEXT = base64.b64decode('').decode('utf-8')


def fail(m):
    print('❌', m, '— 아무것도 저장하지 않았어요.')
    sys.exit(1)


D = {}
for k, p in P.items():
    if not os.path.exists(p):
        fail('파일이 없어요: ' + p)
    raw = open(p, 'rb').read().decode('utf-8')
    D[k] = {'s': raw.replace('\r\n', '\n'), 'crlf': '\r\n' in raw}
    D[k]['orig'] = D[k]['s']


def name(k):
    return os.path.basename(P[k])


def rep(k, label, old, new, done):
    s = D[k]['s']
    if done in s:
        print('✔', name(k), label, '(이미 돼 있음)')
        return
    if s.count(old) != 1:
        fail(f'{name(k)} {label} — 찾을 코드를 못 찾았어요 ({s.count(old)}곳)')
    D[k]['s'] = s.replace(old, new)
    print('✔', name(k), label)


# ── ⋮ 메뉴 ──
k = 'menu'
rep(k, 'import', "import '../screens/paran_intro_screen.dart';\n",
    "import '../screens/paran_intro_screen.dart';\nimport '../screens/feedback_screen.dart';\n",
    done="import '../screens/feedback_screen.dart';")
rep(k, '말풍선 아이콘',
    "const String _kIconClose =\n",
    "// 의견 보내기: 말풍선\nconst String _kIconChat =\n"
    "    '<path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/>';\n"
    "const String _kIconClose =\n",
    done='const String _kIconChat =')
rep(k, '누르면 의견 보내기 화면',
    "      onHelp: () => openPage(ctx, MaterialPageRoute(builder: (_) => const SettingsHelpScreen())),\n",
    "      onHelp: () => openPage(ctx, MaterialPageRoute(builder: (_) => const SettingsHelpScreen())),\n"
    "      onFeedback: () => openPage(ctx, MaterialPageRoute(builder: (_) => const FeedbackScreen())),\n",
    done="onFeedback: () => openPage(ctx,")
rep(k, '메뉴 값 (1)',
    "  final VoidCallback onHelp;\n  final VoidCallback onAlarm;\n",
    "  final VoidCallback onHelp;\n  final VoidCallback onFeedback;\n  final VoidCallback onAlarm;\n",
    done="  final VoidCallback onFeedback;\n")
rep(k, '메뉴 값 (2)',
    "    required this.onHelp,\n    required this.onAlarm,\n",
    "    required this.onHelp,\n    required this.onFeedback,\n    required this.onAlarm,\n",
    done="    required this.onFeedback,\n")
rep(k, "'앱 평가하기' 아래에 '의견 보내기' 줄",
    "                    title: tr.menuRateTitle,\n"
    "                    subtitle: tr.moreRateSub,\n"
    "                    onTap: onRate,\n"
    "                  ),\n",
    "                    title: tr.menuRateTitle,\n"
    "                    subtitle: tr.moreRateSub,\n"
    "                    onTap: onRate,\n"
    "                  ),\n"
    "                  // 의견 보내기 (앱에 대해 말하는 줄끼리: 공유 · 평가 · 의견)\n"
    "                  _MenuCard(\n"
    "                    p: p,\n"
    "                    icon: _kIconChat,\n"
    "                    title: fbText('의견 보내기', 'Send feedback'),\n"
    "                    subtitle: fbText('불편한 점이나 바라는 점', 'Problems or ideas'),\n"
    "                    onTap: onFeedback,\n"
    "                  ),\n",
    done="icon: _kIconChat,")

# ── 도움말 맨 아래 ──
k = 'help'
rep(k, 'import', "import '../l10n/locale_holder.dart';\n",
    "import '../l10n/locale_holder.dart';\nimport 'feedback_screen.dart';\n",
    done="import 'feedback_screen.dart';")
rep(k, "'이메일 문의' 버튼 → '의견 보내기' 화면",
    "                        child: OutlinedButton.icon(\n"
    "                          onPressed: _mailUs,\n",
    "                        child: OutlinedButton.icon(\n"
    "                          onPressed: () {\n"
    "                            const MethodChannel('kr.ssing.catsong/media').invokeMethod('vibrate');\n"
    "                            Navigator.push(context, MaterialPageRoute(builder: (_) => const FeedbackScreen()));\n"
    "                          },\n",
    done="builder: (_) => const FeedbackScreen()));")
rep(k, '버튼 글자·아이콘',
    "                          icon: const Icon(Icons.edit_outlined, size: 19),\n"
    "                          label: Text(tr.emailUs,\n",
    "                          icon: const Icon(Icons.chat_bubble_outline_rounded, size: 18),\n"
    "                          label: Text(fbText('의견 보내기', 'Send feedback'),\n",
    done="icon: const Icon(Icons.chat_bubble_outline_rounded, size: 18),")
rep(k, '메일 주소는 누르면 메일 앱 (예전 방법도 남김)',
    "                      Center(child: Text(_contactMail, style: TextStyle(color: hint, fontSize: 12))),\n",
    "                      // 메일 주소: 누르면 메일 앱 (예전처럼)\n"
    "                      Center(\n"
    "                        child: GestureDetector(\n"
    "                          behavior: HitTestBehavior.opaque,\n"
    "                          onTap: _mailUs,\n"
    "                          child: Padding(\n"
    "                            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 4),\n"
    "                            child: Text(_contactMail,\n"
    "                                style: TextStyle(\n"
    "                                    color: hint, fontSize: 12, decoration: TextDecoration.underline, decorationColor: hint)),\n"
    "                          ),\n"
    "                        ),\n"
    "                      ),\n",
    done="onTap: _mailUs,\n")

for k in D:
    s = D[k]['s']
    if s.count('(') != s.count(')') or s.count('{') != s.count('}') or s.count('[') != s.count(']'):
        fail(name(k) + ' 괄호가 안 맞아요')
changed = [k for k in D if D[k]['s'] != D[k]['orig']]
crlf = D['menu']['crlf']
cur = open(NEW, 'rb').read().decode('utf-8').replace('\r\n', '\n') if os.path.exists(NEW) else None
new_needed = cur != TEXT
if not changed and not new_needed:
    print('이미 적용돼 있어요')
    sys.exit(0)
for k in changed:
    s = D[k]['s']
    if D[k]['crlf']:
        s = s.replace('\n', '\r\n')
    open(P[k], 'wb').write(s.encode('utf-8'))
if new_needed:
    open(NEW, 'wb').write((TEXT.replace('\n', '\r\n') if crlf else TEXT).encode('utf-8'))
    print('✔ 새 파일:', NEW)
print('저장했어요:', ', '.join([name(k) for k in changed] + (['feedback_screen.dart'] if new_needed else [])))
